#include <assert.h>
#include <string.h>

typedef unsigned long long big_int;

class stringx;

class string_buf
{
protected:
  friend class stringx;

  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
  friend class string_buf;

  protected:
    char *chars;
    string_buf *my_buf;

  public:
    stringx(const stringx &cp);
    ~stringx();

    void copy(stringx &cp);

    inline int size() const
    {
      assert(chars);
      return my_buf->char_length;
    }

    inline int length() const
    {
      return size();
    }

    stringx substr(int i = 0, int n = -1) const;

    inline stringx slice(int start, int end) const
    {
      if (start < 0)
        start += length();
      if (end < 0)
        end += length();
      assert(start <= end);
      return substr(start, end-start);
    };

    stringx read_token(char *delim, int start_index = 0, bool ignore_leading = true, bool chop = false);
};

stringx stringx::read_token(char *delim, int start_index, bool ignore_leading, bool chop)
{
	int start = start_index, end;

	if (start_index < 0)
		start_index += length();

	if (ignore_leading) {
		while (strchr(delim, chars[start]) && start < length())
			start++;
	}

	end = start;

	while (!strchr(delim, chars[end]) && end < length())
		end++;

	stringx result = slice(start, end);

	if (chop) {
		stringx tmp = slice(end, length());
		copy(tmp);
	}

	return result;
}
